const received = $input.item.json;
const data = received.body || received;

const language = (data.lang || data.language || 'fr').toLowerCase();
const status = (data.status || 'success').toLowerCase();
const recipient = data.recipient || data.target || 'utilisateur';
const actionId = data.action_id || `notif_${Date.now()}`;
const userId = data.user_id || 'unknown';

let message = data.message || '';
if (!message) {
  if (status === 'success') {
    message = language === 'en'
      ? `The email was sent to ${recipient}.`
      : (language === 'ar'
        ? `تم ارسال البريد الى ${recipient}.`
        : `L'email a ete envoye a ${recipient}.`);
  } else {
    message = language === 'en'
      ? `The email was not sent to ${recipient}.`
      : (language === 'ar'
        ? `لم يتم ارسال البريد الى ${recipient}.`
        : `L'email n'a pas ete envoye a ${recipient}.`);
  }
}

return {
  json: {
    action_id: actionId,
    user_id: userId,
    language,
    status,
    recipient,
    message
  }
};

const tts = $input.item.json;
const base = $item(0).$node['Normalize Gmail Notification'].json;
const audioUrl = tts.audio_url || tts.body?.audio_url || '';

if (!audioUrl) {
  throw new Error('TTS did not return audio_url');
}

return {
  json: {
    ...base,
    audio_url: audioUrl,
    mqtt_voice_topic: 'gob/audio/tts/request',
    mqtt_voice_payload: {
      request_id: $execution.id,
      action_id: base.action_id,
      user_id: base.user_id,
      lang: base.language || 'fr',
      text: base.message,
      url: audioUrl,
      ts: Math.floor(Date.now() / 1000)
    }
  }
};
